class Job:
    name: str
    deps: list[str]

def build_order(jobs: list[Job]) -> Result[list[str], str]:
    job_map = map_from([(job.name, job) for job in jobs])
    for job in jobs:
        if job_map.get(job.name) is None:
            return Err(f"duplicate job: {job.name}")

    for job in jobs:
        for dep in job.deps:
            if job_map.get(dep) is None:
                return Err(f"unknown dependency: {dep}")

    order = []
    while jobs:
        available = filter(jobs, lambda job: all(dep in order for dep in job.deps))
        if not available:
            return Err("cycle detected")
        job = next(available)
        order.append(job.name)
        jobs.remove(job)

    return Ok(order)

