    if str_len(s) == 0:
        return Err("empty")

    units = ["h", "m", "s"]
    seen_units = []
    total_seconds = 0

    i = 0
    while i < str_len(s):
        if s[i].isdigit():
            j = i
            while j < str_len(s) and s[j].isdigit():
                j += 1
            num = parse_int(s[i:j])?
            i = j
            if str_len(i) == 0:
                return Err("missing unit")
            unit = s[i]
            i += 1
            if not contains(units, unit):
                return Err(f"unknown unit: {unit}")
            if not contains(units, unit) or not all(lambda u: not contains(seen_units, u) or units.index(u) < units.index(unit), seen_units):
                return Err(f"unit out of order: {unit}")
            seen_units.append(unit)
            if unit == "h":
