def parse_money(s: str) -> Result[int, str]:
    if s.startswith("-"):
        s = s[1:]
        negate = True
    else:
        negate = False

    if not s.startswith("$"):
        return Err("missing $")

    s = s[1:]
    parts = s.split(".")
    if len(parts) != 1 and len(parts) != 2:
        return Err("bad cents")

    dollars, cents = parts if len(parts) == 2 else (parts[0], "00")

    if not dollars or (dollars[0] == "0" and dollars != "0"):
        return Err("bad dollars")

    if len(cents) != 2:
        return Err("bad cents")

    try:
        dollars = int(dollars.replace(",", ""))
        cents = int(cents)
    except ValueError:
        return Err("bad dollars")

    return Ok(dollars * 100 + cents * (1 if not negate else -1))

