    deps: list[str]

def build_order(jobs: list[Job]) -> Result[list[str], str]:
    job_map = map_from([(job.name, job) for job in jobs])
    if len(job_map) != len(jobs):
        return Err(f"duplicate job: {next(name for name, count in Counter(job.name for job in jobs).items() if count > 1)}")
    for job in jobs:
        for dep in job.deps:
            if dep not in job_map:
                return Err(f"unknown dependency: {dep}")
    order = []
    while jobs:
        available = filter(jobs, lambda job: all(dep in order for dep in job.deps))
        if not available:
            return Err("cycle detected")
        order.extend(available)
        jobs = [job for job in jobs if job not in available]
    return Ok(order)

