def tic_tac_toe(board: list[str]) -> str:
    def has_line(player: str) -> bool:
        for i in range(3):
            if board[i] == player * 3 or board[0][i] == player or board[1][i] == player or board[2][i] == player:
                return True
        if board[0][0] == player and board[1][1] == player and board[2][2] == player:
            return True
        if board[0][2] == player and board[1][1] == player and board[2][0] == player:
            return True
        return False

    x_count = sum(row.count('X') for row in board)
    o_count = sum(row.count('O') for row in board)

    if abs(x_count - o_count) > 1 or (x_count < o_count):
        return "invalid"

    if has_line('X') and x_count != o_count + 1:
        return "invalid"
    if has_line('O') and x_count != o_count:
        return "invalid"

    if has_line('X'):
        return "X wins"
    if has_line('O'):
        return "O wins"
    if '.' not in ''.join(board):
        return "draw"
    return "in progress"

