class Job:
    name: str
    deps: list[str]

def build_order(jobs: list[Job]) -> Result[list[str], str]:
    job_map = map_from(list(map(lambda job: (job.name, job), jobs)))
    for job in jobs:
        if job_map.get(job.name) is None:
            return Err(f"duplicate job: {job.name}")

    for job in jobs:
        for dep in job.deps:
            if job_map.get(dep) is None:
                return Err(f"unknown dependency: {dep}")

    order = []
    placed = set()
    while len(placed) < len(jobs):
        for job in jobs:
            if job.name not in placed and all(dep in placed for dep in job.deps):
                order.append(job.name)
                placed.add(job.name)
                break
        else:
            return Err("cycle detected")

    return Ok(order)

