def k_most_frequent(xs: list[int], k: int) -> list[tuple[int, int]]:
    if k <= 0:
        return []

    count = map_from(map(lambda x: (x, 1), filter(lambda x: x not in map_get(count, x), xs)))
    for x in xs:
        if x in count:
            count[x] += 1

    sorted_count = sorted(count.items(), key=lambda item: (-item[1], item[0]))
    return sorted_count[:k]

