def parse_duration(s: str) -> Result[int, str]:
    if str_len(s) == 0:
        return Err("empty")

    h, m, s = 0, 0, 0
    i = 0
    while i < str_len(s):
        digits = ""
        while i < str_len(s) and s[i].isdigit():
            digits += s[i]
            i += 1

        if i == str_len(s):
            return Err("missing unit")

        unit = s[i]
        i += 1

        if unit not in "hms":
            return Err(f"unknown unit: {unit}")

        if unit == "h":
            if h != 0:
                return Err("unit out of order: h")
            h = int(digits)
        elif unit == "m":
            if m != 0:
                return Err("unit out of order: m")
            m = int(digits)
        elif unit == "s":
            s = int(digits)

    return Ok(h * 3600 + m * 60 + s)

