                if rolls[i + 1] == 10:
                    score += rolls[i + 3]
                i += 1
            elif rolls[i] + rolls[i + 1] == 10:
                score += 10 + rolls[i + 2]
                i += 2
            else:
                score += rolls[i] + rolls[i + 1]
                i += 2

    if i != len(rolls):
        return Err("too many rolls")

