def bowling_score(rolls: list[int]) -> Result[int, str]:
    if any(r < 0 or r > 10 for r in rolls):
        return Err("invalid roll")

    def score_frame(i: int) -> tuple[int, int]:
        if rolls[i] == 10:  # Strike
            return 10, 2
        elif rolls[i] + rolls[i + 1] > 10:
            return rolls[i] + rolls[i + 1], 2
        else:
            return rolls[i] + rolls[i + 1], 2

    score = 0
    i = 0
    while i < len(rolls):
        if i == 9:  # Last frame
            if rolls[i] == 10:  # Strike
                score += 10 + rolls[i + 1] + rolls[i + 2]
                i += 3
            elif rolls[i] + rolls[i + 1] == 10:  # Spare
                score += 10 + rolls[i + 2]
                i += 3
            else:
                score += rolls[i] + rolls[i + 1]
                i += 2
        else:
            s, n = score_frame(i)
            score += s
            i += n

    if i != len(rolls):
        return Err("too many rolls")

    return Ok(score)

