    if day_end <= day_start:
        return []

    # Sort meetings by start time
    meetings.sort(key=lambda m: m.start)

    # Initialize the list of free slots
    free_slots = []

    # Add the initial free slot before the first meeting
    if meetings[0].start > day_start:
        free_slots.append((day_start, meetings[0].start))

    # Iterate through the meetings to find free slots between them
    for i in range(len(meetings) - 1):
        if meetings[i].end < meetings[i + 1].start:
            free_slots.append((meetings[i].end, meetings[i + 1].start))

    # Add the free slot after the last meeting
    if meetings[-1].end < day_end:
        free_slots.append((meetings[-1].end, day_end))

    return free_slots

