def count_live_neighbors(grid: list[str], row: int, col: int) -> int:
    count = 0
    for i in range(max(0, row - 1), min(len(grid), row + 2)):
        for j in range(max(0, col - 1), min(len(grid[i]), col + 2)):
            if i != row or j != col:
                count += 1 if grid[i][j] == "#" else 0
    return count

def life_step(grid: list[str], steps: int) -> list[str]:
    for _ in range(steps):
        new_grid = []
        for i in range(len(grid)):
            new_row = ""
            for j in range(len(grid[i])):
                live_neighbors = count_live_neighbors(grid, i, j)
                if grid[i][j] == "#" and (live_neighbors == 2 or live_neighbors == 3):
                    new_row += "#"
                elif grid[i][j] == "." and live_neighbors == 3:
                    new_row += "#"
                else:
                    new_row += "."
            new_grid.append(new_row)
        grid = new_grid
    return grid

