type OrderEvent = Create(id: str) | Pay(id: str) | Ship(id: str) | Cancel(id: str)

def order_states(events: list[OrderEvent]) -> Result[list[tuple[str, str]], str]:
    orders = map_from([])
    for event in events:
        match event:
            case Create(id):
                if map_get(orders, id) is not None:
                    return Err(f"duplicate order: {id}")
                orders = map_set(orders, id, "created")
            case Pay(id):
                if map_get(orders, id) is None:
                    return Err(f"unknown order: {id}")
                if map_get(orders, id) == "created":
                    orders = map_set(orders, id, "paid")
                else:
                    return Err(f"cannot pay {id} from {map_get(orders, id)}")
            case Ship(id):
                if map_get(orders, id) is None:
                    return Err(f"unknown order: {id}")
                if map_get(orders, id) == "paid":
                    orders = map_set(orders, id, "shipped")
                else:
                    return Err(f"cannot ship {id} from {map_get(orders, id)}")
            case Cancel(id):
                if map_get(orders, id) is None:
                    return Err(f"unknown order: {id}")
                if map_get(orders, id) in ["created", "paid"]:
                    orders = map_set(orders, id, "cancelled")
                else:
                    return Err(f"cannot cancel {id} from {map_get(orders, id)}")
    return Ok(sorted(map_to_list(orders)))

def map_to_list(m: dict[str, str]) -> list[tuple[str, str]]:
