def inventory_ledger(stock: list[Stock], txns: list[Txn]) -> Result[list[Stock], str]:
    stock_map = map_from(map(lambda s: (s.sku, s), stock))
    for i, txn in enumerate(txns, start=1):
        if txn.sku not in stock_map:
            return Err(f"txn {i}: unknown sku {txn.sku}")
        new_qty = stock_map[txn.sku].qty + txn.delta
        if new_qty < 0:
            return Err(f"txn {i}: {txn.sku} would go negative")
        stock_map[txn.sku].qty = new_qty
    return Ok(sorted(stock_map.values(), key=lambda s: s.sku))

