def parse_ipv4(s: str) -> Result[int, str]:
    parts = split(s, ".")
    if len(parts) != 4:
        return Err("expected 4 parts")
    total = 0
    for i, part in enumerate(parts):
        if not (1 <= str_len(part) <= 3):
            return Err(f"bad part: {part}")
        if part == "0":
            continue
        if part[0] == "0":
            return Err(f"bad part: {part}")
        num = parse_int(part)?
        if num < 0 or num > 255:
            return Err(f"bad part: {part}")
        total += num * pow(256, 3 - i)
    return Ok(total)

