def parse_query(s: str) -> Result[list[tuple[str, str]], str]:
    items = filter(lambda item: item, s.split("&"))
    pairs = []
    for item in items:
        parts = item.split("=", 1)
        key = unescape(parts[0].replace("+", " "))
        value = unescape(parts[1] if len(parts) > 1 else "")
        if not key:
            return Err(f"empty key: {item}")
        pairs.append((key, value))
    return Ok(pairs)

