def pig_latin(s: str) -> str:
    words = s.split()
    translated = map(translate_word, words)
    return join(translated, ' ')

def translate_word(word: str) -> str:
    vowels = "aeiou"
    if word.startswith(('q', 'Q')):
        vowels += 'u'
    if word.startswith(('y', 'Y')):
        vowels += 'y'

    for i in range(len(word)):
        if word[i] in vowels:
            if (word[i] == 'u' or word[i] == 'U') and i > 0 and word[i-1] == 'q':
                continue
            return word[i:] + word[:i] + "ay"
    return word + "ay"

