            if e.user not in sessions or sessions[e.user][-1].kind == "logout":
                sessions = map_set(sessions, e.user, sessions.get(e.user, []) + [e])
        elif e.kind == "logout":
            if e.user in sessions and sessions[e.user][-1].kind == "login":
                sessions = map_set(sessions, e.user, sessions[e.user][:-1] + [Session(e.user, "logout", e.time)])
