        if sess[-1].kind == "login":
            sessions = map_set(sessions, user, sess[:-1] + [Session(sess[-1].user, "logout", events[-1].time)])
    return sorted((user, sum(e.time - s.time for s, e in zip(sess, sess[1:]))) for user, sess in sessions.items())

